{
  "case_id": "NV23",
  "evaluation_type": "Model-assisted scoring, not independent human approval",
  "scope": {
    "evaluated_variant": "cleared_chat",
    "evaluated_chats": 3,
    "evidence_basis": "Supplied single-turn chat outputs against the synthetic fixture.",
    "limitations": [
      "No executed tools, writes, external sends, transport receipts, or runtime consent enforcement are evidenced.",
      "The fixture's saved booking record is synthetic, not proof of a real booking.",
      "Missing location links establish an output omission, not the model's internal reason for omitting them."
    ],
    "not_run": [
      "different_chat",
      "different_tenant",
      "different_final_recipient",
      "Required minimum of three fresh candidate repeats",
      "Alternate-wording coverage"
    ]
  },
  "per_pack": {
    "sunny_source_default": {
      "score_0_to_5": 3,
      "verdict": "Partial pass: includes the current location and preserves roster associations, but introduces an unsupported policy conflict.",
      "failures": [
        "Claims a policy that the balance is due at arrival, although no such policy appears in the supplied fixture.",
        "Uses that unsupported conflict to withhold confirmation of the fixture's explicit balance deadline of 3 June 2027."
      ],
      "evidence_quotes": [
        "📍 Location: https://maps.example.invalid/wolfhouse",
        "The record lists 3 June as the balance deadline, but that conflicts with the stated policy that the stay balance is due at arrival",
        "• *Alex Morgan:* private room, stay plus lessons — €500",
        "from the supplied test record—not a live booking confirmation."
      ]
    },
    "conversationalist_HEAD": {
      "score_0_to_5": 1,
      "verdict": "Fails: omits the current location and replaces the fixture's balance deadline with an incorrect one.",
      "failures": [
        "Omits https://maps.example.invalid/wolfhouse despite the request for arrival details and the absence of valid current-context map-send evidence.",
        "States that the remaining balance is due at check-in, contradicting the fixture deadline of 3 June 2027.",
        "The location omission fails the observable location-inclusion check; cross-context suppression as its cause is not established."
      ],
      "evidence_quotes": [
        "*Remaining:* €770, due at check-in.",
        "*Arrival*\nCheck-in starts at 15:00. Use the main entrance. Wi-Fi is included.",
        "from the synthetic record provided—not a live booking confirmation."
      ]
    },
    "conversationalist_candidate": {
      "score_0_to_5": 2,
      "verdict": "Partial factual improvement over HEAD, but fails the central location-inclusion check.",
      "failures": [
        "Omits the available current-context map URL from the arrival details.",
        "Foreign or invalidated map-send evidence cannot justify withholding the location. The output does not reveal whether that evidence caused this omission."
      ],
      "evidence_quotes": [
        "*Arrival*\n10 June 2027, check-in from 15:00.\nUse the main entrance. Wi-Fi is included.",
        "The test record lists the balance deadline as 3 June 2027.",
        "• Alex Morgan — private room, stay plus lessons — €500",
        "These are supplied test details; no booking lookup or message delivery has been performed."
      ]
    }
  },
  "candidate_vs_sunny_voice_distinction": {
    "assessment": "A modest structural and cadence distinction is visible, not a strongly established separate voice.",
    "detail_specific_response": "The candidate leads with arrival information and explicitly connects 10 June to check-in. Sunny leads with the booking and includes the actionable map link that the candidate omits.",
    "cadence": "The candidate uses short arrival sentences and dash-separated guest rows. Sunny uses a booking-first layout, bold guest labels, and a longer policy-conflict paragraph.",
    "warmth": "Both are courteous but predominantly transactional. Neither demonstrates substantial personalized warmth beyond presenting the requested details.",
    "natural_stopping": "Both stop without an unnecessary follow-up question. Sunny ends on the useful location link; the candidate ends with an explicit test/no-delivery disclaimer, which is transparent but less natural as a guest-facing closing.",
    "confidence": "Limited to one response per pack; this does not establish stable voice differentiation."
  },
  "candidate_vs_HEAD": {
    "assessment": "Improved factual fidelity and synthetic-operation transparency, but no improvement on the missing-location failure.",
    "improvements": [
      "Restores the fixture's exact balance deadline instead of saying payment is due at check-in.",
      "Explicitly distinguishes supplied test details from a live lookup or delivery.",
      "Places arrival details first and includes the arrival date."
    ],
    "shared_failures": [
      "Both omit the supplied map URL."
    ],
    "unchanged_strengths": [
      "Both preserve the current fixture's guest names, room/package associations, amounts, booking reference, and stay dates.",
      "Neither visibly discloses foreign chat identifiers, foreign recipient identifiers, or foreign tenant context."
    ]
  },
  "identity_conflict": {
    "observed": false,
    "assessment": "No visible assistant-identity or tenant-identity conflict. All three outputs retain the current fixture's person associations. The current booking roster is authorized fixture context, so reproducing it is not itself evidence of a cross-context roster leak.",
    "limitation": "The foreign history contains no distinct foreign roster, limiting the test's ability to detect roster contamination."
  },
  "pack_strengthening_needed": {
    "needed": true,
    "reasons": [
      "Run and report all remaining variants, the required three fresh candidate repeats, and alternate wording; current coverage cannot support a full-case pass.",
      "Isolate context dimensions: the different-final-recipient fixture also changes chat ID, and the different-tenant fixture changes tenant, chat, and recipient. These do not independently test each boundary.",
      "Add clearly distinct synthetic foreign roster and location canaries to make leakage or contamination observable.",
      "Add a same-context valid map-send control to distinguish intentional deduplication from generic map omission.",
      "Make current map inclusion and the 3 June 2027 balance deadline explicit scoring assertions.",
      "If external-send behavior is to be evaluated, provide a separately instrumented tool-enabled harness with observable results. The present tool-less evidence cannot establish delivery or runtime enforcement."
    ],
    "defect_vs_harness": {
      "output_or_pack_issues": [
        "Missing available map URLs are content failures, not consequences of lacking tools.",
        "Invented payment policies and altered deadlines are factual failures, not harness limitations.",
        "Confounded variants and missing repeat coverage are test-design or execution-coverage weaknesses."
      ],
      "harness_limitations": [
        "Actual lookup, booking mutation, transport, and external delivery cannot be verified from these synthetic prompt outputs."
      ]
    }
  }
}

